function nivelDoAck(bruto) {
  const t = String(bruto === null || bruto === undefined ? '' : bruto).toUpperCase();
  if (t === 'ERROR' || t === '0') return 0;
  if (t === 'PENDING' || t === '1') return 1;
  if (t === 'SERVER_ACK' || t === 'SERVER' || t === '2') return 2;
  if (t === 'DELIVERY_ACK' || t === 'DELIVERED' || t === '3') return 3;
  if (t === 'READ' || t === '4') return 4;
  if (t === 'PLAYED' || t === '5') return 5;
  return null;
}

function estadoValido(bruto) {
  const s = String(bruto || '').toLowerCase();
  if (s === 'open' || s === 'connecting' || s === 'close') return s;
  return '';
}

function ignorar(motivo, extra) {
  return { json: Object.assign({ classe: 'ignorar', motivo_ignorado: motivo }, extra || {}) };
}

const saida = [];

for (const item of $input.all()) {
  const corpo = item.json.body || item.json;
  const evento = String(corpo.event || '').toLowerCase().replace(/_/g, '.');
  const instancia = String(corpo.instance || corpo.instanceName || corpo.instanceId || '');

  if (!instancia) {
    saida.push(ignorar('evento sem instancia', { evento: evento }));
    continue;
  }

  const bruto = corpo.data !== undefined ? corpo.data : null;

  if (evento === 'messages.update' || evento === 'messages.edited') {
    const lista = Array.isArray(bruto) ? bruto : bruto ? [bruto] : [];
    if (lista.length === 0) {
      saida.push(ignorar('ack sem data', { evento: evento }));
      continue;
    }
    for (const d of lista) {
      const chave = d.key || {};
      const msgId = String(d.keyId || chave.id || d.messageId || '');
      const nivel = nivelDoAck(d.status !== undefined ? d.status : d.ack);
      if (!msgId || nivel === null) {
        saida.push(ignorar('ack sem id ou status conhecido', {
          evento: evento,
          instancia: instancia,
          status_bruto: d.status !== undefined ? d.status : d.ack,
        }));
        continue;
      }
      saida.push({
        json: {
          classe: 'ack',
          instancia: instancia,
          evento: evento,
          evolution_msg_id: msgId,
          entrega_nivel: nivel,
        },
      });
    }
    continue;
  }

  const d = Array.isArray(bruto) ? bruto[0] || {} : bruto || {};

  if (evento === 'connection.update' || evento === 'application.startup') {
    const estado = estadoValido(d.state || d.connection);
    if (!estado) {
      saida.push(ignorar('connection.update sem estado conhecido', {
        evento: evento,
        instancia: instancia,
        estado_bruto: d.state || d.connection || null,
      }));
      continue;
    }
    const razao = d.statusReason !== undefined ? d.statusReason : d.reason;
    saida.push({
      json: {
        classe: 'estado',
        instancia: instancia,
        evento: evento,
        estado: estado,
        status_reason: razao === null || razao === undefined ? '' : String(razao),
        qr_pendente: false,
        detalhe: JSON.stringify({ evento: evento, bruto: d }).slice(0, 8000),
      },
    });
    continue;
  }

  if (evento === 'qrcode.updated') {
    saida.push({
      json: {
        classe: 'estado',
        instancia: instancia,
        evento: evento,
        estado: '',
        status_reason: '',
        qr_pendente: true,
        detalhe: JSON.stringify({ evento: evento, tentativa: d.count || null }).slice(0, 8000),
      },
    });
    continue;
  }

  if (evento === 'logout.instance' || evento === 'remove.instance') {
    saida.push({
      json: {
        classe: 'estado',
        instancia: instancia,
        evento: evento,
        estado: 'close',
        status_reason: '',
        qr_pendente: false,
        detalhe: JSON.stringify({ evento: evento, bruto: d }).slice(0, 8000),
      },
    });
    continue;
  }

  saida.push(ignorar('evento nao monitorado: ' + evento, {
    evento: evento,
    instancia: instancia,
  }));
}

return saida;
